function ExecImage(props) {
	const nameTxt = String(props.name).replace('_',' ')
	return(
	<div className="image-and-text">
		<img
			src={props.name}
			alt={nameTxt}
			style={{
				width: "80%",
				height: "80%"
			}}
		/>
		<p style={{ margin: "20px 0 0 0", fontSize: "4vmin", fontWeight: 600 }}>Victor Jia</p>
		<p style={{ margin: 0 }}>2027</p>
	</div>
	);
}
export default ExecImage;
